/* eslint no-console:0 import/extensions:0 */
import 'fantd/src/tag/style/index.less';
import { Tag } from 'fantd';
import React from 'react';
import ReactDOM from 'react-dom';

class Component extends React.Component {

    render() {
        return (
            <div>
                <div style={{ margin: 10 }}>
                    <Tag style={{marginRight:4}} text="example:" />
                    <Tag style={{marginRight:4}} text="已发布" color="#FFA844" bgColor="#FFF7EE" />
                    <Tag style={{marginRight:4}} text="公司置顶" color="#9155F8" bgColor="#F5F0FF" />
                    <Tag style={{marginRight:4}} text="钥匙" color="#4CD964" bgColor="#EFFCF1" />
                    <Tag style={{marginRight:4}} text="无效" color="#8E8E93" bgColor="#F5F5F5" />

                    <Tag style={{marginRight:4}} text="已发布" color="#FFA844" bdColor="#FFA844" />
                    <Tag style={{marginRight:4}} text="公司置顶" color="#9155F8" bdColor="#9155F8" />
                    <Tag style={{marginRight:4}} text="钥匙" color="#4CD964" bdColor="#4CD964" />
                    <Tag style={{marginRight:4}} text="无效" color="#8E8E93" bdColor="#8E8E93" />
                </div>
                <div style={{ margin: 10 }}>
                    <Tag style={{marginRight:4}} text="example:" />
                    <Tag style={{marginRight:4,color:"#FFA844",backgroundColor:"#FFF7EE"}} text="已发布" />
                    <Tag style={{marginRight:4,color:"#9155F8",backgroundColor:"#F5F0FF"}} text="公司置顶" />
                    <Tag style={{marginRight:4,color:"#4CD964",backgroundColor:"#EFFCF1"}} text="钥匙" />
                    <Tag style={{marginRight:4,color:"#8E8E93",backgroundColor:"#F5F5F5"}} text="无效" />

                    <Tag style={{marginRight:4,color:"#FFA844",border:"1px solid #FFA844"}} text="已发布" />
                    <Tag style={{marginRight:4,color:"#9155F8",border:"1px solid #9155F8"}} text="公司置顶" />
                    <Tag style={{marginRight:4,color:"#4CD964",border:"1px solid #4CD964"}} text="钥匙" />
                    <Tag style={{marginRight:4,color:"#8E8E93",border:"1px solid #8E8E93"}} text="无效" />
                </div>
            </div>
        );
    }
}

ReactDOM.render(<Component />, document.getElementById('__react-content'));



